() => {
  // Test at 1200px viewport - check if clicking the margin-toggle reveals sidenotes
  const firstToggle = document.querySelector('.margin-toggle');
  const firstSidenote = document.querySelector('.sidenote');

  return {
    viewport: window.innerWidth,
    toggleExists: !!firstToggle,
    toggleType: firstToggle?.type,
    toggleChecked: firstToggle?.checked,
    sidenoteDisplay: firstSidenote ? getComputedStyle(firstSidenote).display : null,
    sidenoteVisibility: firstSidenote ? getComputedStyle(firstSidenote).visibility : null,
    sidenoteOpacity: firstSidenote ? getComputedStyle(firstSidenote).opacity : null,
  };
}

